INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-131', '한우 1~6개월령 보험가액', 'calf_price * (0.5 if month_age < threshold_month else 1.0)', '{"calf_price":"전전월 전국산지평균 송아지 가격 number>=0","month_age":"사고 월령 integer>=1","threshold_month":"50% 적용 임계 (질병사고 3, 그외 2) integer"}', 'p.655', 'F-131', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-132', '한우 7개월+ 보험가액', 'weight_kg * price_per_kg', '{"weight_kg":"발육표준표 적용 체중 number>0","price_per_kg":"산지가격 적용범위표 kg당 금액 number>0"}', 'p.655', 'F-132', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-133', '젖소 8~12개월령 보험가액 (보간)', 'weaning_price + (mating_price - weaning_price) / 6 * (accident_month - 7)', '{"weaning_price":"분유떼기 암컷 가격 number>=0","mating_price":"수정단계 가격 number>0","accident_month":"사고 월령 integer 8..12"}', 'p.656', 'F-133', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-134', '젖소 19~23개월령 보험가액 (보간)', 'mating_price + (first_birth_price - mating_price) / 6 * (accident_month - 18)', '{"mating_price":"수정단계 가격 number","first_birth_price":"초산우 가격 number","accident_month":"사고 월령 integer 19..23"}', 'p.656', 'F-134', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-135', '젖소 32~39개월령 보험가액 (보간)', 'first_birth_price + (multi_birth_price - first_birth_price) / 9 * (accident_month - 31)', '{"first_birth_price":"초산우 가격 number","multi_birth_price":"다산우 가격 number","accident_month":"사고 월령 integer 32..39"}', 'p.657', 'F-135', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-136', '젖소 56~66개월령 보험가액 (보간)', 'multi_birth_price + (old_birth_price - multi_birth_price) / 12 * (accident_month - 55)', '{"multi_birth_price":"다산우 가격 number","old_birth_price":"노산우 가격 number","accident_month":"사고 월령 integer 56..66"}', 'p.657', 'F-136', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-137', '이용물 처분액 (정산자료)', 'carcass_price * 0.75', '{"carcass_price":"도축장발행 정산자료 지육금액 number>=0"}', 'p.654', 'F-137', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-138', '이용물 처분액 (정산자료 X)', 'carcass_weight * carcass_price_per_kg * 0.75', '{"carcass_weight":"도체 중량 (kg) number>0","carcass_price_per_kg":"축산물품질평가원 고시 등급별 전국평균 지육가격 (원/kg) number>0"}', 'p.654', 'F-138', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-139', '종모돈 보험가액', 'sow_price * 1.20', '{"sow_price":"종빈돈 보험가액 number>0"}', 'p.659', 'F-139', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-140', '110kg 비육돈 수취가격', 'pork_price_per_kg * 110 * 0.768', '{"pork_price_per_kg":"직전 5영업일 평균돈육대표가격 (전체, 탕박) number>0"}', 'p.661', 'F-140', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-141', '비육돈 보험가액 (선형보간)', 'piglet_price + (applied_weight - 30) * (pig_110kg_price - piglet_price) / 80', '{"piglet_price":"자돈가격 (30kg 기준) number>0","applied_weight":"적용체중 (kg) integer 35..105","pig_110kg_price":"110kg 비육돈 수취가격 (F-140 결과) number>0"}', 'p.661', 'F-141', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-142', '산란계 20~70주 보험가액', 'max(egg_price - egg_production_cost, 10) * 0.70 * (550 - accident_age_days)', '{"egg_price":"직전 5영업일 계란 1개 평균가격 (가중평균) number>0","egg_production_cost":"계란 1개 생산비 = 77 number=77","accident_age_days":"사고 일령 integer 1..550"}', 'p.663', 'F-142', 2026);
