INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-144', '이익률 (축산휴지)', 'max((avg_pig_price - operation_cost) / avg_pig_price, 0.165)', '{"avg_pig_price":"두당 비육돈 (100kg 기준) 평균가격 number>0","operation_cost":"통계청 발표 비육돈 평균경영비 number>=0"}', 'p.673', 'F-144', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-145', '축산휴지손해 보험가액', 'breeding_sow_count * 10 * avg_pig_price * profit_rate', '{"breeding_sow_count":"종빈돈 마리수 (후보돈/임신·분만·포유 제외) integer>=1","avg_pig_price":"두당 비육돈 평균가격 number>0","profit_rate":"이익률 (F-144 결과) number 0..1"}', 'p.674', 'F-145', 2026);
